// Shared plan meters. Only CLI-reported quota is displayed in the native app.
const planUsage = (() => {
  let snapshot={}, selected='', selectedRoot=null;
  const names={claude:'Claude Code',codex:'Codex',gemini:'Google / Gemini',cursor:'Cursor',grok:'Grok',glm:'GLM'};
  function agents(){
    if(!live&&!snapshot.subscriptions)return ['claude','codex'];
    const c=aiConnections.snapshot();
    const cli=['claude'].filter(id=>c.workerHealth?.[id]==='signedIn' && c.workers?.[id]===(id==='codex'?'ChatGPT login':'Claude plan login'));
    const fresh=Number.isFinite(snapshot.checkedAt)&&Math.abs(Date.now()/1000-snapshot.checkedAt)<300;
    return [...cli,...Object.keys(names).filter(id=>!cli.includes(id)&&fresh&&typeof snapshot.subscriptions?.[id]?.plan==='string'&&snapshot.subscriptions[id].plan.length)];
  }
  function windowsFor(id){
    const now=Date.now()/1000;
    if(!Number.isFinite(snapshot.checkedAt)||snapshot.checkedAt>now+5||now-snapshot.checkedAt>300)return [];
    const windows=snapshot.subscriptions?.[id]?.windows||snapshot.agents?.[id]||[];
    return windows.filter(w=>Number.isInteger(w.remaining)&&w.remaining>=0&&w.remaining<=100&&Number.isFinite(w.resetsAt)&&w.resetsAt>now).sort((a,b)=>(a.minutes===10080?-2:a.minutes===300?-1:a.minutes)-(b.minutes===10080?-2:b.minutes===300?-1:b.minutes)).slice(0,2);
  }
  function period(w){return w.minutes===10080?'7 days':w.minutes===300?'5 hours':w.label||'Plan allowance'}
  function ring(w,r,index){
    return '<circle class="usage-track" cx="20" cy="20" r="'+r+'"/><circle class="usage-progress '+(index===0?'usage-week':'usage-hours')+(w?'':' usage-unknown')+'" cx="20" cy="20" r="'+r+'" pathLength="100" stroke-dasharray="'+(w?100-w.remaining:0)+' 100"/>';
  }
  function label(id){const windows=windowsFor(id);return names[id]+'. '+(windows.length?windows.map(w=>period(w)+': '+(100-w.remaining)+'% used').join('. '):'Usage unavailable')}
  function meter(id,root){const windows=windowsFor(id);return '<button type="button" class="usage-meter" data-usage-agent="'+id+'" aria-label="'+attr(label(id))+'" aria-expanded="'+(selected===id&&selectedRoot===root)+'" title="'+attr(label(id))+'"><svg viewBox="0 0 40 40" aria-hidden="true">'+(windows.length?windows.map((w,i)=>ring(w,i?14:18,i)).join(''):ring(null,18,0))+'</svg><span class="usage-provider '+id+'" aria-hidden="true">'+providerUsageMarks[id]+'</span></button>'}
  function details(id){
    const windows=windowsFor(id),plan=snapshot.subscriptions?.[id]?.plan;
    return '<section class="usage-details" aria-label="'+names[id]+' plan usage"><div class="usage-detail-heading"><strong>'+names[id]+(plan?' · '+esc(plan):'')+'</strong><button type="button" data-usage-close aria-label="Close usage details">'+icon('x')+'</button></div>'+(windows.length?windows.map((w,i)=>'<div class="usage-detail-row"><span><i class="usage-dot usage-'+(i?'hours':'week')+'"></i>'+esc(period(w))+'</span><strong>'+(100-w.remaining)+'% used</strong></div><p class="usage-reset">Resets '+esc(new Date(w.resetsAt*1000).toLocaleString(undefined,{weekday:'short',hour:'numeric',minute:'2-digit'}))+'</p>').join(''):'<p>Usage unavailable. The provider has not reported a current quota.</p>')+'<p class="usage-note">'+(windows.length===2?'Outer: '+esc(period(windows[0]))+' · Inner: '+esc(period(windows[1])):windows.length?'Ring: '+esc(period(windows[0])):'No usage percentage is estimated.')+(!live?' · Sample values':'')+'</p></section>';
  }
  function mount(parent,placement,before=null){
    if(!parent)return;
    let root=parent.querySelector(':scope > .plan-usage');
    if(!root){root=document.createElement('div');root.className='plan-usage usage-'+placement;root.setAttribute('aria-label','Active plan usage');parent.insertBefore(root,before)}
    root.hidden=!agents().length;
    const ids=agents(),slots=Math.ceil(ids.length/2);
    root.style.setProperty('--usage-count',ids.length);
    const items=ids.map(id=>meter(id,root));
    const anchored=placement==='notch'||placement==='modal';
    root.classList.toggle('usage-notch',anchored);
    const html=items.join('');
    if(root.innerHTML!==html)root.innerHTML=html;
    if(selectedRoot===root && !agents().includes(selected)){selected='';selectedRoot=null}
    return root;
  }
  function paint(){
    document.documentElement.style.setProperty('--usage-row-height',agents().length?'34px':'0px');
    mount(document.querySelector('.toolbar-actions'),'workspace',document.querySelector('.toolbar-actions')?.firstChild);
    for(const actions of document.querySelectorAll('.deck-tools-actions'))mount(actions,'deck',actions.firstChild);
    mount(document.querySelector('#island'),'notch');
    const compact=document.body.classList.contains('notch-first');
    if(!compact||!document.querySelector('#handoff-review'))document.querySelector('#modal > .usage-modal')?.remove();
    if(document.querySelector('#handoff-review')){
      if(compact){
        document.querySelector('#modal .usage-review')?.remove();
        mount(document.querySelector('#modal'),'modal');
      }else mount(document.querySelector('#modal .dialog-title'),'review',document.querySelector('#modal .dialog-title > .icon-btn'));
    }
    if(selectedRoot?.isConnected && selected){
      // In compact sheets details take up real space and are measured by the native layout.
      const home=selectedRoot.classList.contains('usage-notch')&&!selectedRoot.classList.contains('usage-modal');
      const review=selectedRoot.classList.contains('usage-review')||selectedRoot.classList.contains('usage-modal');
      const parent=home?document.querySelector('#notch-home .home-content'):review?document.querySelector('#modal .dialog-body'):selectedRoot.parentElement;
      let panel=parent.querySelector(':scope > .usage-details-host');
      if(!panel){panel=document.createElement('div');panel.className='usage-details-host';parent.insertBefore(panel,home||review?parent.children[1]:null)}
      // The host keeps the panel stable through background quota refreshes.
      const html=details(selected);if(panel.innerHTML!==html)panel.innerHTML=html;
    }else{selected='';selectedRoot=null;document.querySelectorAll('.usage-details-host').forEach(el=>el.remove())}
  }
  document.addEventListener('click',e=>{
    const button=e.target.closest('[data-usage-agent]');
    if(button){
      const root=button.closest('.plan-usage'),id=button.dataset.usageAgent;
      const close=selected===id&&selectedRoot===root;
      document.querySelectorAll('.usage-details-host').forEach(el=>el.remove());
      if(root.classList.contains('usage-notch')&&!root.classList.contains('usage-modal')){showHome(true);paint()}
      selectedRoot=root;
      selected=close?'':id;paint();document.querySelector('.usage-details-host [data-usage-close]')?.focus();updateBounds(true);return;
    }
    if(e.target.closest('[data-usage-close]')){const root=selectedRoot;selected='';selectedRoot=null;paint();root?.querySelector('button')?.focus();updateBounds(true)}
  });
  document.addEventListener('workspace-changed',()=>queueMicrotask(paint));
  document.addEventListener('plan-usage',e=>{snapshot=e.detail||{};paint();updateBounds(true)});
  document.addEventListener('connection-state',()=>{paint();updateBounds(true);workerRouting.request()});
  new MutationObserver(()=>paint()).observe(document.querySelector('#modal'),{childList:true});
  new MutationObserver(()=>paint()).observe(document.querySelector('#notch-home .home-content'),{childList:true});
  if(!live){const now=Date.now()/1000;snapshot={checkedAt:now,agents:{claude:[{minutes:10080,remaining:32,resetsAt:now+172800},{minutes:300,remaining:58,resetsAt:now+7200}],codex:[{minutes:10080,remaining:68,resetsAt:now+259200},{minutes:300,remaining:22,resetsAt:now+3600}]}}}
  paint();updateBounds(true);workerRouting.request();
  setInterval(()=>{if(!document.hidden){paint();updateBounds(true);workerRouting.request()}},120000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){paint();updateBounds(true);workerRouting.request()}});
  return {paint,count:()=>agents().length};
})();
